#include "encounter_scene.hpp"
#include <iostream>
#include <source_location>
unsigned checks=0;void check(bool v,const std::source_location l=std::source_location::current()){++checks;if(!v)throw std::runtime_error("Meira scene check="+std::to_string(checks)+" line="+std::to_string(l.line()));}
void ack(soew::EncounterScene&s){for(unsigned i=0;i<4;++i)s.tick(0,false);for(unsigned i=0;i<2;++i)s.tick(soew::OK,true);}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("assets");for(unsigned shot=0;shot<3;++shot){auto s=soew::EncounterScene::load(argv[1],1,int(shot),1,2,3);s.combat_enabled=s.survival_enabled=s.pickup_enabled=true;s.enable_effects();s.enable_bombing();s.enable_preboss();s.midboss2_enabled=s.transitions_enabled=true;std::vector<std::uint32_t> pixels(640*400);for(unsigned f=0;f<12000&&!s.dialogue.active();++f){s.life.invincibility=200;s.tick(0);check(!s.runtime.blocked);}check(s.dialogue.active());for(unsigned box=0;box<24;++box){while(s.dialogue.phase==soew::StageDialogue::Phase::SlideIn||s.dialogue.phase==soew::StageDialogue::Phase::Text||s.dialogue.phase==soew::StageDialogue::Phase::IntroAppearance)s.tick(soew::Shot,true);s.render(pixels);check(s.dialogue.current==box);ack(s);}for(unsigned i=0;i<24;++i)s.tick(0);check(s.meira_enabled&&!s.midboss2_enabled&&s.meira_appearance);s.pickups.power=80;for(unsigned f=0;f<20000&&!s.meira.done;++f){s.life.invincibility=200;s.tick(soew::Shot);if(f%17==0)s.render(pixels);}std::cout<<"combat done="<<s.meira.done<<" damage="<<s.meira.damage_taken<<" phase="<<s.meira.phase_frame<<" state="<<s.meira.state<<" pos="<<s.meira.left[0]<<","<<s.meira.top[0]<<" scroll="<<s.scroll.line<<'\n';check(s.meira.done&&s.meira.damage_taken>=2400);s.tick(0);for(unsigned box=24;box<35;++box){while(s.dialogue.phase==soew::StageDialogue::Phase::SlideIn||s.dialogue.phase==soew::StageDialogue::Phase::Text)s.tick(soew::Shot,true);s.render(pixels);check(s.dialogue.current==box);ack(s);}check(s.transition.phase==soew::StageTransition::Phase::BonusAck);ack(s);ack(s);for(unsigned f=0;f<142;++f)s.tick(0);auto n=s.next_stage();check(n.stage==2&&n.pickups.power==80&&n.life.lives==s.life.lives&&n.life.bombs==s.life.bombs);for(unsigned f=0;f<42;++f)n.tick(0);for(unsigned f=0;f<300;++f){n.life.invincibility=200;n.tick(0);}check(n.ticks==300&&!n.runtime.blocked);std::cout<<"shot="<<shot<<" Meira_damage="<<s.meira.damage_taken<<" stage3="<<n.ticks<<'\n';}std::cout<<"meira_scene_checks="<<checks<<" failures=0\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
